// Span + deadband
const nums = Object.values(limits).filter(x => x !== null && typeof x === 'number');
const span = nums.length >= 2 ? Math.max(...nums) - Math.min(...nums) : 100;
const db   = span * DEADBAND / 100;

function exceedLevel(v, L) {
    if (L.HH !== null && v > L.HH) return 'HH';
    if (L.H  !== null && v > L.H)  return 'H';
    if (L.LL !== null && v < L.LL) return 'LL';
    if (L.L  !== null && v < L.L)  return 'L';
    return 'NORMAL';
}
function shouldClear(v, cur, L) {
    if (cur === 'HH' && L.HH !== null && v <= L.HH - db) return true;
    if (cur === 'H'  && L.H  !== null && v <= L.H  - db) return true;
    if (cur === 'LL' && L.LL !== null && v >= L.LL + db) return true;
    if (cur === 'L'  && L.L  !== null && v >= L.L  + db) return true;
    return false;
}

