    if (st.pending === newLvl) {
        st.pendingN++;
        if (st.pendingN >= ON_DELAY && st.level !== newLvl) {
            outLvl = newLvl;
            st.level = newLvl;
            st.pending = null; st.pendingN = 0;
            changed = true;
        }
    } else { st.pending = newLvl; st.pendingN = 1; }
} else if (clearing) {
    if (st.level !== 'NORMAL') {
        outLvl = 'NORMAL';
        st.level = 'NORMAL';
        st.pending = null; st.pendingN = 0;
        changed = true;
